1	package world
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"syscall"
8	)
9	
10	// Record 是一次成功保存留下的、可供读取的记录。
11	type Record struct {
12		// ID 是记录标识。
13		ID RecordID
14		// Parent 是父记录标识；槽首条记录为空。
15		Parent RecordID
16		// SlotFirst 表示这是其所在槽的首条记录。
17		SlotFirst bool
18		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
19		State State
20	}
21	
22	func acquireSharedLock(dir string) (*fileLock, error) {
23		path := dir + "/lock"
24		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
25		if err != nil {
26			return nil, err
27		}
28		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
29			f.Close()
30			return nil, err
31		}
32		return &fileLock{f: f}, nil
33	}
34	
35	// loadAndVerifyLocked 读取记录文件，校验其记录格式版本、内容校验和（校验和
36	// 已包含父记录关系）、父记录是否存在，以及世界数据是否自洽。
37	//
38	// 记录格式只支持 recordFormatVersion：格式编号缺失、为零、为负或为其他
39	// 正整数的记录按损坏处理，即使校验和匹配、世界状态合法、规则版本可被
40	// 调用方接受也不交付——目录能打开不代表每条记录都是当前功能理解的格式。
41	// 格式校验先于内容校验和：校验和载荷的布局本身由格式定义，未知格式的
42	// 记录无法解释其校验语义。格式问题与规则版本分别判断，格式错误一律报
43	// CorruptError，绝不报成 VersionRejectedError。
44	//
45	// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
46	// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
47	// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
48	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
49		env, err := loadRecord(recordPath(a.dir, id))
50		if err != nil {
51			if errors.Is(err, os.ErrNotExist) {
52				return nil, &NotFoundError{Record: id}
53			}
54			return nil, &CorruptError{Record: id, Reason: err.Error()}
55		}
56		if env.ID != id {
57			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
58		}
59		if env.Format != recordFormatVersion {
60			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("不支持的记录格式版本: %d", env.Format)}
61		}
62		if got := computeChecksum(env); got != env.Checksum {
63			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
64		}
65		// 父记录关系必须落到一个真实存在的记录上。
66		if env.Parent != "" {
67			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
68				if errors.Is(err, os.ErrNotExist) {
69					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
70				}
71				return nil, err
72			}
73		}
74		// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
75		// 其余状态合法，也按损坏处理，不自动把时间改成零。
76		if env.State.Time < 0 {
77			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
78		}
79		if err := validateInitialData(InitialData{
80			Seed:       env.State.Seed,
81			Rules:      env.State.Rules,
82			Characters: env.State.Characters,
83		}); err != nil {
84			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
85		}
86		return env, nil
87	}
88	
89	func versionAccepted(version string, accepted []string) bool {
90		for _, v := range accepted {
91			if v == version {
92				return true
93			}
94		}
95		return false
96	}
97	
98	func envToRecord(env *envelope) Record {
99		return Record{
100			ID:        env.ID,
101			Parent:    env.Parent,
102			SlotFirst: env.SlotFirst,
103			State:     cloneState(env.State),
104		}
105	}
106	
107	// Latest 读取槽当前最新记录。
108	//
109	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
110	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（格式版本不受支持、
111	// 校验和不符、父记录缺失、无法解析、时间片为负）时返回 *CorruptError。
112	// 格式与版本分别判断：格式不受支持的记录一律报损坏，不报版本拒绝。
113	// 读取不会改写存档。
114	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
115		if !validSlotName(slot) {
116			return Record{}, &NotFoundError{Slot: slot}
117		}
118		lock, err := acquireSharedLock(a.dir)
119		if err != nil {
120			return Record{}, err
121		}
122		defer lock.release()
123	
124		id, err := a.readLatestLocked(slot)
125		if err != nil {
126			return Record{}, err
127		}
128		env, err := a.loadAndVerifyLocked(id)
129		if err != nil {
130			if ce, ok := err.(*CorruptError); ok {
131				ce.Slot = slot
132			}
133			return Record{}, err
134		}
135		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
136			return Record{}, &VersionRejectedError{
137				Slot:     slot,
138				Record:   id,
139				Version:  env.State.Rules.Version,
140				Accepted: append([]string(nil), acceptedVersions...),
141			}
142		}
143		return envToRecord(env), nil
144	}
145	
146	// Record 按标识读取槽的一份历史记录（覆盖后的旧记录仍可读取）。
147	//
148	// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
149	// 且记录必须属于该槽的历史链。读取不会改写存档，也不会改变规则版本。
150	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
151		if !validSlotName(slot) {
152			return Record{}, &NotFoundError{Slot: slot}
153		}
154		lock, err := acquireSharedLock(a.dir)
155		if err != nil {
156			return Record{}, err
157		}
158		defer lock.release()
159	
160		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
161			return Record{}, err
162		}
163		env, err := a.loadAndVerifyLocked(id)
164		if err != nil {
165			if ce, ok := err.(*CorruptError); ok {
166				ce.Slot = slot
167			}
168			return Record{}, err
169		}
170		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
171			return Record{}, &VersionRejectedError{
172				Slot:     slot,
173				Record:   id,
174				Version:  env.State.Rules.Version,
175				Accepted: append([]string(nil), acceptedVersions...),
176			}
177		}
178		return envToRecord(env), nil
179	}
180	
181	// History 返回槽的历史记录元信息，按该槽保存生效的次序排列（最新在
182	// 前），到槽首条记录为止；分支槽只含它自己保存成功的记录，不会跨入
183	// 分支来源槽。次序来自槽指针内嵌的历史索引，与文件修改时间无关。该
184	// 方法只做只读遍历，不改写任何数据；无法解析的记录会被略过。
185	func (a *Archive) History(slot string) ([]RecordInfo, error) {
186		if !validSlotName(slot) {
187			return nil, &NotFoundError{Slot: slot}
188		}
189		lock, err := acquireSharedLock(a.dir)
190		if err != nil {
191			return nil, err
192		}
193		defer lock.release()
194	
195		history, err := a.slotHistoryLocked(slot)
196		if err != nil {
197			return nil, err
198		}
199		infos := make([]RecordInfo, 0, len(history))
200		for _, id := range history {
201			env, err := loadRecord(recordPath(a.dir, id))
202			if err != nil {
203				continue
204			}
205			infos = append(infos, RecordInfo{
206				ID:        env.ID,
207				Parent:    env.Parent,
208				SlotFirst: env.SlotFirst,
209				Version:   env.State.Rules.Version,
210			})
211		}
212		return infos, nil
213	}
214	
215	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
216	// 版本可接受的已保存记录。
217	//
218	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
219	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
220	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
221	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
222	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
223	// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
224	// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
225	//
226	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
227	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
228	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
229	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
230	// 不会被选中。
231	//
232	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
233	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
234	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
235	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
236	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
237		if !validSlotName(slot) {
238			return Record{}, &NotFoundError{Slot: slot}
239		}
240		lock, err := acquireSharedLock(a.dir)
241		if err != nil {
242			return Record{}, err
243		}
244		defer lock.release()
245	
246		history, err := a.slotHistoryLocked(slot)
247		if err != nil {
248			return Record{}, err
249		}
250	
251		env, err := a.firstRecoverableLocked(history, acceptedVersions)
252		if err != nil {
253			var ue *UnrecoverableError
254			if errors.As(err, &ue) {
255				ue.Slot = slot
256			}
257			return Record{}, err
258		}
259		return envToRecord(env), nil
260	}
261	
262	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
263	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
264	//
265	// 文件缺失、截断、格式版本不受支持、校验和不符、记录标识不符、父关系异常、
266	// 时间片为负或世界状态不自洽的记录一律越过（不读其中的父标识或槽首标记）；
267	// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
268	// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
269	// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
270	// 补全）。
271	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
272		var lastReason string
273		for _, id := range history {
274			env, verifyErr := a.loadAndVerifyLocked(id)
275			if verifyErr != nil {
276				lastReason = verifyErr.Error()
277				continue
278			}
279			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
280				lastReason = (&VersionRejectedError{
281					Record:  id,
282					Version: env.State.Rules.Version,
283				}).Error()
284				continue
285			}
286			return env, nil
287		}
288	
289		if lastReason == "" {
290			lastReason = "槽中没有任何可确认归属的历史记录"
291		}
292		return nil, &UnrecoverableError{Reason: lastReason}
293	}
